MAKE CODE: P1AM-100 Motor Start/Stop Seal-in
language arduino
// P1AM-100: Motor Start/Stop with Seal-in Logic
// Slot 1: Discrete Input Module
//   Channel 1: Start Button (Normally Open)
//   Channel 2: Stop Button (Normally Closed)
// Slot 2: Discrete Output Module
//   Channel 1: Motor Contactor
// Logic: Motor runs if Start is pressed OR Motor is already running,
// AND Stop is NOT pressed (NC contact is closed/true when not pressed).

#include <P1AM.h>

const int inSlot = 1;
const int outSlot = 2;
const int startPin = 1;
const int stopPin = 2;
const int motorPin = 1;

bool motorRunning = false;

void setup() {
  Serial.begin(115200);
  // Initialize P1AM modules
  while (!P1.init()) {
    ; // Wait for modules to initialize
  }
}

void loop() {
  // Read inputs
  // Start is NO: true when pressed
  bool startPressed = P1.readDiscrete(inSlot, startPin);

  // Stop is NC: true when NOT pressed (circuit closed)
  bool stopNotPressed = P1.readDiscrete(inSlot, stopPin);

  // Seal-in logic:
  // (Start pressed OR Motor already running) AND (Stop not pressed)
  motorRunning = (startPressed || motorRunning) && stopNotPressed;

  // Write output
  P1.writeDiscrete(motorRunning, outSlot, motorPin);
}
END
